sp_SalvarEnderecoEmpresa	ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION	CREATE DEFINER=`root`@`%` PROCEDURE `sp_SalvarEnderecoEmpresa`(\n\n    IN p_idEmpresa INT, IN p_Logradouro VARCHAR(200), IN p_Numero VARCHAR(20),\n\n    IN p_Complemento VARCHAR(50), IN p_Bairro VARCHAR(80),\n\n    IN p_Cidade VARCHAR(60), IN p_Estado VARCHAR(60), IN p_CEP VARCHAR(12)\n\n)\nBEGIN\n\n    DECLARE v_id INT DEFAULT NULL;\n\n    SELECT idEndereco INTO v_id FROM Endereco WHERE idEmpresa=p_idEmpresa AND fAtivo=1 LIMIT 1;\n\n    IF v_id IS NULL THEN\n\n        INSERT INTO Endereco (idEmpresa,Logradouro,Numero,Complemento,Bairro,Cidade,Estado,Pais,CEP,fAtivo)\n\n        VALUES (p_idEmpresa,p_Logradouro,p_Numero,p_Complemento,p_Bairro,p_Cidade,p_Estado,'Brasil',p_CEP,1);\n\n    ELSE\n\n        UPDATE Endereco SET Logradouro=p_Logradouro, Numero=p_Numero, Complemento=p_Complemento,\n\n            Bairro=p_Bairro, Cidade=p_Cidade, Estado=p_Estado, CEP=p_CEP\n\n        WHERE idEndereco=v_id;\n\n    END IF;\n\nEND	utf8mb4	utf8mb4_0900_ai_ci	utf8mb4_0900_ai_ci
